//! Runtime bindings cannot replace a generated module wrapper's own names.
use super::*;

pub(super) fn validate(
    id: &str,
    module: &crate::parser::Module,
    project: &Project,
    options: &CompilerOptions,
) -> Vec<Diagnostic> {
    if !crate::parser::has_module_syntax(&module.declarations)
        || !matches!(
            project.module_kind(id, options.module_kind),
            ModuleKind::CommonJs | ModuleKind::Amd | ModuleKind::Umd | ModuleKind::System
        )
    {
        return Vec::new();
    }
    let tokens = crate::lex(id, &module.source).unwrap_or_default();
    let mut diagnostics = Vec::new();
    for declaration in &module.declarations {
        let (name, declared) = match declaration {
            Declaration::Variable(value) => (&value.name, value.declared),
            Declaration::Function(value) => (&value.name, value.declared || value.overload),
            Declaration::Class(value) => (&value.name, false),
            Declaration::Enum(value) => (&value.name, value.declared),
            _ => continue,
        };
        if declared || !matches!(name.as_str(), "require" | "exports") {
            continue;
        }
        let span = declaration.span();
        if let Some(name_token) = tokens
            .iter()
            .find(|token| token.text == *name && span.start <= token.start && token.end <= span.end)
        {
            diagnostics.push(
                Diagnostic::error(
                    DiagnosticCode::DuplicateDeclaration,
                    name_token.span(id),
                    "runtime binding collides with a generated module name",
                )
                .with_typescript(2441, vec![name.clone(), name.clone()]),
            );
        }
    }
    diagnostics
}
